with flagged as (select *, case when lag(txn_time) over (partition by txn_type order by txn_time, id) is null or txn_time > lag(txn_time) over (partition by txn_type order by txn_time, id) + interval '14' day then 1 else 0 end as new_group_flag from transactions) select *, sum(new_group_flag) over (partition by txn_type order by txn_time, id rows between unbounded preceding and current row) as session_id from flagged;
